]

interface Props {
  activeFilters: Set<string>
  onToggleFilter: (id: string) => void
  onClearAll: () => void
}

function InteractiveFiltersImpl({ activeFilters, onToggleFilter, onClearAll }: Props) {
  return (
    <section
      aria-labelledby="filters-heading"
      className="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm"
    >
      <div className="mb-3 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="text-sm">🎛️</span>
          <h3 id="filters-heading" className="text-sm font-bold text-slate-900">تصفية النتائج</h3>
        </div>
        {activeFilters.size > 0 && (
          <button
            type="button"
            onClick={onClearAll}
            className="text-[10px] font-medium text-slate-400 transition-colors hover:text-rose-500"
          >
            مسح الكل ({activeFilters.size})
          </button>
        )}
      </div>
      <div className="flex flex-wrap gap-2">
        {FILTERS.map(filter => {
          const active = activeFilters.has(filter.id)
          return (
            <button
              key={filter.id}
              type="button"
              onClick={() => onToggleFilter(filter.id)}
              className={`flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-xs font-bold transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-primary-400/20 ${
                active
                  ? 'border-primary-300 bg-primary-50 text-primary-700 shadow-sm'
                  : 'border-slate-200 bg-white text-slate-500 hover:border-primary-200 hover:text-primary-600'
              }`}
              aria-pressed={active}
            >
              <span aria-hidden>{filter.icon}</span>
              <span>{filter.label}</span>
            </button>
          )
        })}
      </div>
    </section>
  )
}

export const InteractiveFilters = memo(InteractiveFiltersImpl)

import {
  getDisplayValue,
  SESSION_FIELD_LABELS,
  type TravelSession,
} from '../utils/travelSession'

const SUMMARY_FIELDS: (keyof TravelSession)[] = [
  'destination',
  'adults',
  'budgetAmount',
  'durationDays',
  'departureDate',
  'departureCity',
  'children',
  'tripPurpose',
  'visaStatus',
]

interface Props {
  session: TravelSession
}

export default function LiveSummaryCard({ session }: Props) {
  return (
    <section className="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm">
      <div className="mb-3 flex items-center gap-2">
        <span className="text-base">📋</span>
        <h2 className="text-sm font-bold text-slate-900">ملخص رحلتك</h2>
      </div>
      <div className="flex flex-wrap gap-2">
        {SUMMARY_FIELDS.map(field => {
          const val = session[field]
          const known = val !== null && val !== undefined && val !== '' && !(typeof val === 'number' && val === 0)
          const label = SESSION_FIELD_LABELS[String(field)] ?? String(field)
          const display = known ? getDisplayValue(field, session) : label
          return (
            <div
              key={String(field)}
              className={`flex items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-medium transition-all duration-300 ${
                known
                  ? 'bg-emerald-50 text-emerald-700 border border-emerald-200'
                  : 'bg-slate-50 text-slate-400 border border-slate-100'
              }`}
            >
              <span className={`text-[10px] ${known ? 'text-emerald-500' : 'text-slate-300'}`}>
                {known ? '✓' : '○'}
              </span>
              <span className={known ? 'font-bold' : ''}>
                {known ? `${label}: ${display}` : label}
              </span>
            </div>
          )
        })}
      </div>
    </section>
  )
}
